import os
from alibabacloud_green20191224 import client as green_client
from alibabacloud_tea_openapi.models import Config

def flag_unsafe_spans(text: str) -> str:
    """Replace unsafe spans in the input text with redacted tokens using Alibaba Cloud Content Moderation."""
    cfg = Config(
        access_key_id=os.getenv("ALIBABA_CLOUD_ACCESS_KEY_ID"),
        access_key_secret=os.getenv("ALIBABA_CLOUD_ACCESS_KEY_SECRET"),
        endpoint="green.cn-beijing.aliyuncs.com"
    )
    green = green_client.GreenClient(cfg)
    request = green.CreateTextScanRequest(
        async_=False,
        tasks=[
            {
                "data_id": "generated_id",
                "content": text,
                "scenes": ["text"]
            }
        ]
    )
    response = green.text_scan(request)
    unsafe_spans = []
    for result in response.body.data:
        for unsafe in result.suggestion_dict.get("text", {}):
            if unsafe.level in ("danger", "warning"):
                unsafe_spans.append(
                    (result.offset, result.offset + result.length)
                )
    for start, end in sorted(unsafe_spans, reverse=True):
        text = f"{text[:start]}[REDACTED]{text[end:]}"
    return text
